import { ArabicShaper } from "./shapers/ArabicShaper.js";
import { IndicShaper } from "./shapers/IndicShaper.js";
import { HangulShaper } from "./shapers/HangulShaper.js";
import { HebrewShaper } from "./shapers/HebrewShaper.js";
import { MyanmarShaper } from "./shapers/MyanmarShaper.js";
import { ThaiShaper } from "./shapers/ThaiShaper.js";
