//#region src/fs.js
function openSync(filename, postscriptName) {
	let buffer = fs.readFileSync(filename);
	return create(buffer, postscriptName);
}
async function open(filename, postscriptName, callback) {
	if (typeof postscriptName === "function") {
		callback = postscriptName;
		postscriptName = null;
	}
	let buffer = await fs.promises.readFile(filename);
	return create(buffer, postscriptName);
}
//#endregion
export { create, defaultLanguage, logErrors, open, openSync, registerFormat, registerShaper, setDefaultLanguage };
